// Check the shared token, then the body, then hand the message to the send node.
// Fail closed: every call is refused until a token of at least 16 characters is set in the tab variable ALERT_TOKEN.
const token = env.get('ALERT_TOKEN') || '';
if (token.length < 16) {
    msg.statusCode = 503;
    msg.payload = { error: 'set ALERT_TOKEN (at least 16 characters) in the properties of this flow' };
    return [null, msg];
}
const given = String(msg.req.headers['x-token'] || '');
let different = given.length ^ token.length; // compare every character, so the time does not tell how many matched
for (let i = 0; i < token.length; i++) {
    different |= (given.charCodeAt(i) || 0) ^ token.charCodeAt(i);
}
if (different !== 0) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return [null, msg];
}
const body = msg.payload || {};
if (typeof body.to !== 'string' || typeof body.message !== 'string' || !body.message) {
    msg.statusCode = 400;
    msg.payload = { error: 'send {"to": "+12025550123", "message": "text"}' };
    return [null, msg];
}
msg.to = body.to;
msg.payload = body.message;
return [msg, null];

msg.statusCode = 202;
msg.payload = { message_id: msg.messageId, status: msg.payload.status && msg.payload.status.state };
return msg;

msg.statusCode = 502;
msg.payload = { error: msg.error.message };
return msg;
